mapper.insert:
INSERT INTO customer (
    user_id, company, industry, address, city, province, postal_code
) VALUES (
    #{userId}, #{company}, #{industry}, #{address}, #{city}, #{province}, #{postalCode}
)

mapper.select:
SELECT COUNT(DISTINCT c.customer_id) FROM customer c INNER JOIN user u ON c.user_id = u.user_id INNER JOIN salesperson sp ON sp.user_id = #{salespersonUserId} INNER JOIN `order` o ON c.customer_id = o.customer_id AND o.salesperson_id = sp.salesperson_id
AND (c.company LIKE #{searchText} OR u.real_name LIKE #{searchText})
AND c.industry = #{industry}
